#define main individual_probe_main
#include "probe.c"
#undef main
/* Ordered tick-1965 allocation shapes, identical bytes for both strategies.
 * Known-idle storage isolates lifecycle costs; no simulation/HUD/FPS claim. */
int main(int argc,char**argv){CHECK(argc==2);int w[128],h[128],n=0;const char *actual=getenv("ENG_BURST_PAYLOAD_DIR");char meta[1024];if(actual)snprintf(meta,sizeof meta,"%s/payloads.meta",actual);FILE *f=fopen(actual?meta:argv[1],"r");CHECK(f);if(actual){int index,bw,bh;while(n<128&&fscanf(f,"%d %d %d %d %d",&index,w+n,h+n,&bw,&bh)==5){CHECK(index==n&&w[n]==bw&&h[n]==bh);n++;}}else while(n<128&&fscanf(f,"%d %d",w+n,h+n)==2)n++;fclose(f);CHECK(n>0&&n<128);CHECK(!SDL_Init(SDL_INIT_VIDEO));SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_ES);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,2);SDL_Window*window=SDL_CreateWindow("burst",0,0,640,480,SDL_WINDOW_OPENGL);CHECK(window&&SDL_GL_CreateContext(window));SDL_GL_SetSwapInterval(0);fprintf(stderr,"GL=%s renderer=%s\n",glGetString(GL_VERSION),glGetString(GL_RENDERER));GLuint retained[128];unsigned char *payload[128];size_t total=0;for(int i=0;i<n;i++){size_t b=(size_t)w[i]*h[i]*4;total+=b;payload[i]=malloc(b);CHECK(payload[i]);for(size_t j=0;j<b;j++)payload[i][j]=(unsigned char)(j*17+i);if(actual){char path[1024];snprintf(path,sizeof path,"%s/payload-%d.rgba",actual,i);FILE*p=fopen(path,"rb");CHECK(p&&fread(payload[i],1,b,p)==b&&fgetc(p)==EOF);fclose(p);}retained[i]=allocate(w[i],h[i],2,0,payload[i]);}glFinish();puts("sample,case,requests,upload_bytes,storage_bytes,allocation_us,upload_us,retirement_us,complete_us");for(int s=-5;s<40;s++)for(int step=0;step<2;step++){int keep=(s+step+6)%2;double allocation=0,upload=0,retire=0,t,finish;GLuint fresh[128];glFinish();for(int i=0;i<n;i++){GLuint id=retained[i];if(!keep){t=now();glGenTextures(1,&id);glBindTexture(GL_TEXTURE_2D_ARRAY,id);parameters(GL_TEXTURE_2D_ARRAY);glTexImage3D(GL_TEXTURE_2D_ARRAY,0,GL_RGBA8,w[i],h[i],2,0,GL_RGBA,GL_UNSIGNED_BYTE,NULL);allocation+=now()-t;fresh[i]=id;}else glBindTexture(GL_TEXTURE_2D_ARRAY,id);t=now();glTexSubImage3D(GL_TEXTURE_2D_ARRAY,0,0,0,0,w[i],h[i],1,GL_RGBA,GL_UNSIGNED_BYTE,payload[i]);upload+=now()-t;}t=now();glFinish();finish=now()-t;if(!keep)for(int i=0;i<n;i++){t=now();GLsync fence=glFenceSync(GL_SYNC_GPU_COMMANDS_COMPLETE,0);CHECK(glClientWaitSync(fence,GL_SYNC_FLUSH_COMMANDS_BIT,1000000000ULL)!=GL_TIMEOUT_EXPIRED);glDeleteSync(fence);glDeleteTextures(1,fresh+i);retire+=now()-t;}CHECK(glGetError()==GL_NO_ERROR);if(s>=0)printf("%d,%s,%d,%zu,%zu,%.3f,%.3f,%.3f,%.3f\n",s,keep?"retain_idle":"fresh_retire",n,total,total*2,allocation*1e6,upload*1e6,retire*1e6,finish*1e6);}glDeleteTextures(n,retained);SDL_Quit();return 0;}
